AppProto AppLayerProtoDetectDetect(AppLayerProtoDetectThreadCtx *tctx,
                                   Flow *f,
                                   uint8_t *buf,
                                   uint32_t buflen,
                                   uint8_t ipproto,
                                   uint8_t direction) {
    AppProto alproto = ALPROTO_UNKNOWN;

    /* Check if passive monitoring is complete */
    if (!FlowIsPMEnabled(f)) {
        /* Attempt to detect protocol using PM methods */
        alproto = AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
        if (alproto != ALPROTO_UNKNOWN) {
            if (alproto == ALPROTO_DCERPC && ipproto == IPPROTO_UDP) {
                /* Proceed with other detection methods for DCERPC over UDP */
                alproto = AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction);
            }
            return alproto;
        }
    } else {
        /* PM is complete; check using post-processing methods */
        alproto = AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction);
        if (alproto != ALPROTO_UNKNOWN)
            return alproto;
    }

    /* Check against expectation list if protocol is still unknown */
    if (alproto == ALPROTO_UNKNOWN)
        alproto = AppLayerProtoDetectExpectation(f, ipproto);

    return alproto;
}

AppProto AppLayerProtoDetectDetectFlow(AppLayerProtoDetectThreadCtx *tctx,
                                       Flow *f, uint8_t *buf, uint32_t buflen,
                                       uint8_t ipproto, uint8_t direction) {
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowGetAppLayerProto(f)) {
        /* Attempt passive protocol detection first */
        AppProto pm_alproto = AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
        if (pm_alproto != ALPROTO_UNKNOWN) {
            if (pm_alproto == ALPROTO_DCERPC && ipproto == IPPROTO_UDP) {
                AppProto pp_alproto = AppLayerProtoDetectPP(tctx, f, ipproto, direction);
                if (pp_alproto != ALPROTO_UNKNOWN) {
                    alproto = pp_alproto;
                } else {
                    alproto = pm_alproto;
                }
            } else {
                alproto = pm_alproto;
            }
        } else {
            AppProto pp_alproto = AppLayerProtoDetectPP(tctx, f, ipproto, direction);
            if (pp_alproto != ALPROTO_UNKNOWN) {
                alproto = pp_alproto;
            } else {
                alproto = ALPROTO_UNKNOWN;
            }
        }
    } else {
        alproto = FlowGetAppLayerProto(f);
    }

    if (alproto == ALPROTO_UNKNOWN) {
        AppProto expected_alproto = AppLayerProtoDetectExpectationCheck(f, ipproto, direction);
        if (expected_alproto != ALPROTO_UNKNOWN) {
            alproto = expected_alproto;
        }
    }

    return alproto;
}

AppProto AppLayerProtoDetectDetect(
    AppLayerProtoDetectThreadCtx *tctx,
    Flow *f,
    uint8_t *buf,
    uint32_t buflen,
    uint8_t ipproto,
    uint8_t direction)
{
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowGetAppProto(f)) {
        if (!FlowGetPmCompleted(f)) {
            alproto = AppLayerProtoDetectDetectPM(tctx, f, buf, buflen, ipproto, direction);

            if (alproto == ALPROTO_DCERPC && ipproto == IPPROTO_UDP) {
                alproto = AppLayerProtoDetectDetectPP(tctx, f, buf, buflen, ipproto, direction);
            }

            if (alproto != ALPROTO_UNKNOWN) {
                FlowSetAppProto(f, alproto);
            } else {
                FlowSetPmCompleted(f, 1);
            }
        } else {
            alproto = AppLayerProtoDetectDetectPP(tctx, f, buf, buflen, ipproto, direction);

            if (alproto != ALPROTO_UNKNOWN) {
                FlowSetAppProto(f, alproto);
            }
        }

        if (alproto == ALPROTO_UNKNOWN) {
            alproto = AppLayerProtoDetectCheckExpectationList(f);
        }
    }

    return alproto;
}

AppProto AppLayerProtoDetectDetect(AppLayerProtoDetectThreadCtx *tctx,
                                   Flow *f,
                                   uint8_t *buf,
                                   uint32_t buflen,
                                   uint8_t ipproto,
                                   uint8_t direction) {
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowHasAppLayerProtoDetectionDone(f, direction)) {
        alproto = AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
        if (alproto == ALPROTO_DCERPC && ipproto == IPPROTO_UDP) {
            /* DCERPC over UDP needs additional checks */
            AppProto tmp = AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction);
            if (tmp != ALPROTO_UNKNOWN)
                alproto = tmp;
        }
        FlowSetAppLayerProtoDetectionDone(f, direction);
    } else {
        alproto = AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction);
    }

    if (alproto == ALPROTO_UNKNOWN) {
        alproto = AppLayerProtoDetectExpectation(f, ipproto, direction);
    }

    return alproto;
}

